import socket

def scan_ports(host: str, ports: list[int]) -> dict[int, bool]:
    result = {}
    for port in ports:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(1)
            try:
                s.connect((host, port))
                result[port] = True
            except (socket.timeout, ConnectionRefusedError):
                result[port] = False
    return result
```

